task<void> fetch_all(std::vector<std::string> urls, Sink& sink) {
  for (auto& url : urls)
    sink.emit(co_await http_get(url));   // resumes with the response, no callback
}
// completion-token style: http_get(url, use_awaitable) / http_get(url, callback)
